// Curated excerpts from VOA The Inside Story. Links identify the original program and transcript.
const news = [
{id:'voa-149',level:'原版',title:'Competing with China',zh:'中美经济竞争',date:'2024-06-20',text:'China has the world’s second largest economy behind the United States, and both countries are competing for global dominance.',translation:'中国是仅次于美国的全球第二大经济体，两国正在争夺全球主导地位。',source:'https://www.voanews.com/a/7663948.html',video:'https://www.voanews.com/a/7663955.html',phrase:'and both',ipa:'/ən boʊθ/',han:'近似「恩-波欧斯」',tip:'and 在非重读时可以弱化成 /ən/；舌尖先碰上齿龈发 /n/，马上闭唇发 both 的 /b/。both 末尾 /θ/ 要把舌尖轻放上下齿之间送气，不是汉语的“斯”。'},
{id:'voa-158',level:'原版',title:'A Restaurant Faces Rising Costs',zh:'通胀下的美国餐厅',date:'2024-08-22',text:'Instead of a busy restaurant filled with customers, Perez is dealing with empty tables, staff shortages, and rising costs due to inflation.',translation:'佩雷斯的餐厅不再顾客盈门，而是面对空桌、员工短缺，以及通胀造成的成本上涨。',source:'https://www.voanews.com/a/7753801.html',video:'https://www.voanews.com/a/7753800.html',phrase:'of a',ipa:'/əv ə/',han:'近似「额-弗-额」',tip:'of 弱读为 /əv/，下唇轻触上齿发 /v/，声带振动，然后直接滑到 a 的 /ə/。不要在两个词之间停顿，也不要给 /v/ 加完整的“福”。'},
{id:'voa-160',level:'原版',title:'AI and Disinformation',zh:'人工智能与虚假信息',date:'2024-09-05',text:'Worldwide political disinformation is on the rise. And advances in artificial intelligence make it harder to spot.',translation:'全球政治虚假信息正在增加，而人工智能的进步使它更难被识别。',source:'https://www.voanews.com/a/7773107.html',video:'https://www.voanews.com/a/7771538.html',phrase:'is on',ipa:'/ɪz ɑn/',han:'近似「一兹-昂」',tip:'is 末尾 /z/ 是带振动的“兹”音，直接接到 on 的开口元音 /ɑ/，听作 /ɪ zɑn/。不要停顿，也不要把 /z/ 读成清音 /s/。'},
{id:'voa-111',level:'原版',title:'The Promise and Risk of AI',zh:'人工智能的风险与机遇',date:'2023-09-28',text:'But what exactly is it and how does it work?',translation:'但它到底是什么，又是如何运作的？',source:'https://www.voanews.com/a/7289199.html',video:'https://www.voanews.com/a/7289143.html',phrase:'does it',ipa:'/dʌz ɪt/',han:'近似「达-兹一特」',tip:'先把 does 读作 /dʌz/，再把结尾 /z/ 接到 it 的 /ɪ/，连成 /dʌ.zɪt/。/ʌ/ 是放松的短元音，不是拉长的“啊”。'}
];
articles.push(...news);
function newsCard(a){return `<button class="article-card" data-open="${a.id}"><div class="card-top"><span class="pill">VOA · 电视新闻</span><span>${a.date}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.zh)} →</p></button>`}
home=function(){let done=Object.values(state.checks[day()]||{}).filter(Boolean).length;return `<div class="layout"><div><section class="hero"><div class="tag">REAL NEWS · REAL ENGLISH</div><h1>跟着真实新闻，<br>练出自然美语。</h1><p>看美国新闻节目，从真实报道里的句子开始听、读、背。</p><button class="btn" data-open="voa-149">开始练习 &nbsp; ↗</button></section><div class="notice"><b>手机没声音？</b>先按一下测试按钮，再调高媒体音量、检查静音和蓝牙输出。<br><button class="btn secondary" data-action="audio-test">▶ 测试声音</button><span id="audio-status" class="hint" style="margin-left:8px"></span></div><div class="section-head"><div><h2>美国电视新闻</h2><p>VOA 原节目 + 新闻原句，标注报道日期</p></div><button class="link" data-page="library">查看全部 →</button></div><div class="grid">${news.map(newsCard).join('')}</div><p class="hint">目前精选 4 个真实节目，每个配一小段原句和连读讲解；完整节目约 25 分钟，不是实时新闻。VOA 原视频在来源网站播放，可能因网络而不可用。</p></div><aside class="right-column"><div class="right-card"><div class="date-row"><h3>今日小任务</h3><span class="pill">${done} / 4</span></div><p>每天一点，记得更牢。</p><div class="mini-progress"><span style="width:${done*25}%"></span></div>${tasks()}<button class="link" data-page="reviews">查看复习计划 →</button></div><div class="right-card quote"><div class="mark">“</div><strong>Listen closely.<br>Speak confidently.</strong><p>听清楚，慢慢说。</p></div></aside></div>`};
library=function(){return `<div class="page-header"><div class="eyebrow">REAL NEWSROOM ENGLISH</div><h1>美国电视新闻</h1><p class="sub">选真实节目，先听新闻原声，再练习摘出的句子。</p></div><div class="notice">精选 4 个 VOA《The Inside Story》节目与新闻原句；节目为 2023—2024 年报道，非实时新闻。当前只提供短句精练，不是每级 10 篇三分钟全文。每篇来源页提供完整节目及文字稿，视频能否播放取决于网络。</div><div class="grid">${news.map(newsCard).join('')}</div>`};
const oldReading=reading;
reading=function(){let a=news.find(n=>n.id===current);if(!a)return oldReading();let r=state.reviews[a.id];return `<div class="reading"><button class="back" data-page="library">← 返回新闻</button><div class="page-header"><div class="eyebrow" style="margin-top:25px">VOA · THE INSIDE STORY · ${a.date}</div><h1>${esc(a.title)}</h1><p class="sub">${esc(a.zh)} · 历史电视节目节选 · 非实时新闻</p></div><div class="box"><div class="row"><a class="btn" href="${a.video}" target="_blank" rel="noopener">▶ 看 VOA 新闻原视频</a><a class="btn light" href="${a.source}" target="_blank" rel="noopener">查看 VOA 完整文字稿 ↗</a></div><p class="hint">原节目约 25 分钟；点击上方按钮到 VOA 看原主播视频。下方是短句摘录，设备朗读只是辅助示范，不是主播原音。</p></div><div class="toolbar"><button class="btn" data-action="play-all">▶ 设备朗读</button><button class="btn light" data-action="stop">■ 停止</button><label class="speed">速度 <select id="speed" style="border:0;background:transparent;color:inherit"><option value="0.7">0.7×</option><option value="0.8">0.8×</option><option value="0.9">0.9×</option><option value="1">1.0×</option><option value="1.2">1.2×</option></select></label><button class="btn secondary" data-action="mask">${masked?'显示原文':'遮住原文'}</button></div><p class="hint">轻点单词查发音，长按后松手听单词。原句来自 VOA，点击上方可查看完整文字稿。</p><div class="box"><div class="textblock">${masked?'● ● ● ● ● ● ●':tokenize(esc(a.text))}</div><p class="hint">${esc(a.translation)}</p></div><div class="training"><h3>逐句跟读</h3><p>${masked?'先不看原文，尝试说出来。':esc(a.text)}</p><div class="row"><button class="btn secondary" data-action="play-all">▶ 听句子</button><button class="btn" data-action="record">● 录音</button><button class="btn light" data-action="stop-record">■ 结束</button><button class="btn light" data-action="play-record">▷ 回听</button><button class="btn light" data-assess="sentence">🎯 发音评测</button></div><p id="rec-status" class="hint">先听原声，再跟读和回听；评测需要自行接入微软语音服务。</p><div id="assessment-result"></div></div><div class="box"><h3 style="font-size:16px;margin:0 0 12px">拆开练 · 新闻里的连读</h3><div class="tip"><strong>${esc(a.phrase)}</strong><span>${esc(a.ipa)}</span><p><b>中文近似：</b>${esc(a.han)}。汉字只是找感觉，不能代替音标。</p><p><b>怎么发：</b>${esc(a.tip)}</p><div class="row"><button class="btn secondary" data-say="${esc(a.phrase)}">▶ 听连读示范</button><button class="btn light" data-action="record">● 录音</button><button class="btn light" data-action="stop-record">■ 结束</button><button class="btn light" data-action="play-record">▷ 回听</button><button class="btn light" data-assess="phrase">🎯 连读评测</button></div><p class="hint">示范由设备语音合成；发音随设备而异，连读也不是每次都会发生。</p></div></div><div class="box"><div class="date-row"><div><h3 style="margin:0;font-size:15px">加入间隔复习</h3><p class="hint">${r?`当前第 ${r.stage+1} 次复习 · 下次 ${r.next}`:'完成首次学习后加入计划'}</p></div><button class="btn" data-action="start-review">${r?'重设计划':'加入复习'}</button></div></div><div class="notice">音标评分是机器估计，不能保证每个音都判断准确。公开网站不会保存你的微软令牌；评测时音频会发送至微软。</div></div>`};
// Safari requires speech to start directly within a user gesture.
speak=function(s){let out=$('#audio-status');if(!('speechSynthesis'in window)){if(out)out.textContent='此浏览器不支持语音，请用 Safari。';else alert('此浏览器不支持语音，请用 Safari。');return}try{let u=new SpeechSynthesisUtterance(s);u.lang='en-US';u.rate=Number(state.speed)||0.9;let vs=speechSynthesis.getVoices();let v=vs.find(x=>x.lang.toLowerCase()==='en-us'&&/samantha/i.test(x.name))||vs.find(x=>x.lang.toLowerCase()==='en-us');if(v)u.voice=v;u.onerror=e=>{if(e.error==='canceled'||e.error==='interrupted')return;if(out)out.textContent='播放失败：请检查音量和蓝牙，再试一次。';else status('播放失败：请用 Safari 并检查音量和蓝牙。')};u.onstart=()=>{if(out)out.textContent='正在播放；若听不到，请检查音量或蓝牙。'};speechSynthesis.cancel();speechSynthesis.resume();speechSynthesis.speak(u);if(out)out.textContent='正在尝试播放，请调高媒体音量。'}catch(e){if(out)out.textContent='无法启动播放，请尝试 Safari。'}};
let speechToken='',speechRegion='',speechRecognizer=null;
function assessmentSetup(target){$('.assessment-panel')?.remove();let panel=document.createElement('div');panel.className='modal-bg assessment-panel';panel.innerHTML=`<div class="modal"><button class="close" data-close-assess>✕</button><div class="eyebrow">PRONUNCIATION ASSESSMENT</div><h2 style="font:700 21px 'Noto Sans SC',sans-serif">连接音标评测</h2><p>此功能使用微软 Azure Speech，提供单词和音素准确度估计。需要你自己拥有 Azure Speech 资源，并提供对应区域和短期访问令牌；服务可能收费。</p><p>录音会发送给微软进行评测。令牌只保留在本页面内存，关闭页面后清除。请勿在聊天或公开场合分享令牌。</p><label class="hint">资源区域，例如 eastus</label><input id="speech-region" class="assessment-input" placeholder="eastus" value="${esc(speechRegion)}"><label class="hint">短期访问令牌（不是订阅密钥）</label><input id="speech-token" class="assessment-input" type="password" autocomplete="off" placeholder="粘贴临时令牌"><p class="hint"><a href="https://learn.microsoft.com/azure/ai-services/speech-service/rest-text-to-speech#authentication" target="_blank" rel="noopener">了解微软临时令牌 ↗</a></p><div class="row"><button class="btn" data-connect-assess="${target}">连接并开始录音</button><button class="btn light" data-close-assess>取消</button></div><p id="assess-setup-status" class="hint"></p></div>`;document.body.append(panel)}
function loadSdk(){return new Promise((resolve,reject)=>{if(window.SpeechSDK)return resolve();let s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/microsoft-cognitiveservices-speech-sdk@1.46.0/distrib/browser/microsoft.cognitiveservices.speech.sdk.bundle-min.js';s.onload=resolve;s.onerror=()=>reject(Error('评测组件加载失败，请检查网络。'));document.head.appendChild(s)})}
function resultHtml(json){let n=json.NBest?.[0],p=n?.PronunciationAssessment||{},words=n?.Words||[];if(!n)return '<p>未获得评分，请再试一次。</p>';return `<div class="box" style="margin-top:14px"><b>发音估计 ${Math.round(p.PronScore??p.AccuracyScore??0)} / 100</b><p class="hint">颜色提示模型的音素准确度估计；低分不一定意味着没读出，请结合回听判断。</p>${words.map(w=>`<div class="tip"><b>${esc(w.Word)}</b> <small> ${w.ErrorType==='Omission'||w.PronunciationAssessment?.ErrorType==='Omission'?'可能遗漏':Math.round(w.PronunciationAssessment?.AccuracyScore??0)+' 分'}</small><div class="row" style="margin-top:6px">${(w.Phonemes||[]).map(x=>{let score=x.PronunciationAssessment?.AccuracyScore;return `<span class="pill" style="background:${score<60?'#fae7df':score<80?'#fff2d7':'#eaf2e8'}">/${esc(x.Phoneme)}/ ${score==null?'—':Math.round(score)}</span>`}).join('')}</div></div>`).join('')}</div>`}
async function assess(target){if(!speechToken||!speechRegion){assessmentSetup(target);return}let a=news.find(n=>n.id===current);if(target!=='word'&&!a)return;let out=target==='word'?$('#assessment-result-modal'):$('#assessment-result');if(!out)return;out.innerHTML='<p class="hint">正在连接并录音，请在麦克风提示中选择允许，然后读出目标内容。</p>';try{await loadSdk();let cfg=SpeechSDK.SpeechConfig.fromAuthorizationToken(speechToken,speechRegion);cfg.speechRecognitionLanguage='en-US';cfg.outputFormat=SpeechSDK.OutputFormat.Detailed;let ac=SpeechSDK.AudioConfig.fromDefaultMicrophoneInput();speechRecognizer=new SpeechSDK.SpeechRecognizer(cfg,ac);let reference=target==='word'?modalWord:(target==='phrase'?a.phrase:a.text);let conf=SpeechSDK.PronunciationAssessmentConfig.fromJSON(JSON.stringify({referenceText:reference,gradingSystem:'HundredMark',granularity:'Phoneme',phonemeAlphabet:'IPA',enableMiscue:true}));conf.applyTo(speechRecognizer);speechRecognizer.recognizeOnceAsync(res=>{try{if(res.reason!==SpeechSDK.ResultReason.RecognizedSpeech){out.innerHTML='<p class="hint">未识别到语音或令牌已失效，请检查麦克风、网络和令牌后重试。</p>';return}let raw=res.properties.getProperty(SpeechSDK.PropertyId.SpeechServiceResponse_JsonResult);out.innerHTML=resultHtml(JSON.parse(raw))}catch(e){out.innerHTML='<p class="hint">无法读取评测结果，请重试。</p>'}finally{speechRecognizer?.close();speechRecognizer=null}},err=>{out.innerHTML='<p class="hint">评测失败：请检查令牌、区域、网络和麦克风权限。</p>';speechRecognizer?.close();speechRecognizer=null})}catch(e){out.innerHTML='<p class="hint">评测无法启动：请检查网络、组件与麦克风权限。</p>'}}
const baseWordModal=wordModal;wordModal=function(w){baseWordModal(w);let box=document.querySelector('.modal-bg:not(.assessment-panel) .modal');if(box){let row=box.querySelector('.row'),btn=document.createElement('button');btn.className='btn light';btn.dataset.assess='word';btn.textContent='🎯 单词评测';row.appendChild(btn);let result=document.createElement('div');result.id='assessment-result-modal';box.appendChild(result)}};
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.action==='audio-test')speak('Hello. This is your English sound check.');if(b.dataset.assess)assess(b.dataset.assess);if(b.dataset.closeAssess!==undefined)document.querySelector('.assessment-panel')?.remove();if(b.dataset.connectAssess){let token=$('#speech-token').value.trim(),region=$('#speech-region').value.trim();if(!token||!/^[-a-z0-9]+$/i.test(region)){$('#assess-setup-status').textContent='请输入有效的区域和临时令牌。';return}speechToken=token;speechRegion=region;let target=b.dataset.connectAssess;document.querySelector('.assessment-panel')?.remove();assess(target)}});
render();
